<?php defined('ABSPATH') || exit; get_header(); ?>
<div class="container"><?php hpv_breadcrumbs(); ?></div>
<?php while (have_posts()) : the_post(); $product = get_post_type() === 'hpv_product'; $project = get_post_type() === 'hpv_project'; ?>
<?php if ($product) : ?>
<article class="product-single"><section class="container product-detail"><figure class="product-detail-image"><?php hpv_image(get_the_ID(), 'hpv-wide', '', true); ?><?php if (hpv_is_illustration(get_the_ID())) : ?><figcaption>Hình ảnh minh họa sản phẩm / ứng dụng</figcaption><?php endif; ?></figure><div class="product-summary"><span class="section-kicker"><?php $terms = hpv_product_terms(get_the_ID()); echo $terms ? esc_html($terms[0]->name) : 'Sản phẩm Hải Phát Vina'; ?></span><h1><?php the_title(); ?></h1><p class="product-lead"><?php echo esc_html(get_the_excerpt()); ?></p><div class="detail-price"><?php echo esc_html(get_post_meta(get_the_ID(), '_hpv_price', true) ?: 'Liên hệ báo giá'); ?><?php $unit = get_post_meta(get_the_ID(), '_hpv_unit', true); if ($unit) { echo '<small> / ' . esc_html($unit) . '</small>'; } ?></div><dl class="product-specs"><?php foreach (array('material' => 'Quy cách', 'application' => 'Ứng dụng', 'warranty' => 'Bảo hành') as $key => $label) { $value = get_post_meta(get_the_ID(), '_hpv_' . $key, true); if ($value) { echo '<div><dt>' . esc_html($label) . '</dt><dd>' . esc_html($value) . '</dd></div>'; } } ?></dl><div class="product-actions"><a class="button button--orange" href="#contact">Yêu cầu báo giá <?php echo hpv_icon('arrow'); ?></a><a class="button button--outline" href="<?php echo esc_url(hpv_zalo_url()); ?>" target="_blank" rel="noopener noreferrer">Trao đổi qua Zalo</a></div><p class="detail-note">Quy cách, giá và phạm vi cung cấp được xác nhận theo nhu cầu thực tế.</p></div></section><section class="section soft-section"><div class="container content-layout"><div class="prose"><h2>Thông tin sản phẩm</h2><?php the_content(); wp_link_pages(); ?></div><aside class="content-sidebar"><h3>Chuẩn bị để tư vấn dễ hơn</h3><ul class="check-list"><li><?php echo hpv_icon('check'); ?>Kích thước & số lượng</li><li><?php echo hpv_icon('check'); ?>Mục đích sử dụng</li><li><?php echo hpv_icon('check'); ?>Khu vực giao / lắp đặt</li><li><?php echo hpv_icon('check'); ?>Ảnh vị trí thực tế</li></ul><a class="button button--navy" href="<?php echo esc_url(hpv_phone_url()); ?>"><?php echo hpv_icon('phone'); ?><?php echo esc_html(hpv_get('phone')); ?></a></aside></div></section></article>
<?php else : ?>
<article class="container editorial-single">
    <header class="article-header"><span class="section-kicker"><?php echo $project ? (get_post_meta(get_the_ID(), '_hpv_demo', true) === '1' ? 'Gợi ý ứng dụng minh họa' : 'Công trình Hải Phát Vina') : 'Cẩm nang Hải Phát Vina'; ?></span><h1><?php the_title(); ?></h1>
    <?php if (!$project) : $article_categories = get_the_category(); ?><div class="article-meta"><?php if ($article_categories) : ?><a class="article-category" href="<?php echo esc_url(get_category_link($article_categories[0]->term_id)); ?>"><?php echo esc_html(hpv_category_label($article_categories[0])); ?></a><?php endif; ?><time datetime="<?php echo esc_attr(get_the_date('c')); ?>"><?php echo esc_html(get_the_date('d/m/Y')); ?></time><span><?php echo (int) hpv_reading_minutes(); ?> phút đọc (ước tính)</span></div><?php endif; ?>
    <p><?php echo esc_html(get_the_excerpt()); ?></p></header>
    <figure class="editorial-cover"><?php hpv_image(get_the_ID(), 'hpv-wide', '', true); ?><?php if (hpv_is_illustration(get_the_ID())) : ?><figcaption>Hình ảnh minh họa</figcaption><?php endif; ?></figure>
    <div class="article-reading-layout"><?php if (!$project) : ?><aside class="article-toc" data-article-toc hidden><details open><summary>Trong bài viết này</summary><nav aria-label="Mục lục bài viết"></nav></details></aside><?php endif; ?><div class="prose editorial-content" <?php echo !$project ? 'data-article-content' : ''; ?>><?php the_content(); wp_link_pages(); ?><?php if (!$project && has_tag()) : ?><div class="article-tags"><?php the_tags('', '', ''); ?></div><?php endif; ?></div></div>
    <?php if (!$project) : ?><div class="editorial-footer"><span>Thông tin hữu ích cho lựa chọn của bạn.</span><button class="copy-article" type="button" data-copy-article="<?php echo esc_url(get_permalink()); ?>" aria-live="polite">Sao chép liên kết bài viết</button><span class="sr-only" role="status"></span></div><?php endif; ?>
    <?php if (comments_open() || get_comments_number()) { comments_template(); } ?>
</article>
<?php endif; ?>
<?php endwhile; ?>
<?php if (isset($product) && $product) : ?><section class="section related-section"><div class="container"><div class="section-heading"><h2>Tham khảo thêm</h2><a class="text-link" href="<?php echo esc_url(hpv_products_url()); ?>">Tất cả sản phẩm <?php echo hpv_icon('arrow'); ?></a></div><div class="product-grid"><?php $related_args = array('post_type' => 'hpv_product', 'post__not_in' => array(get_queried_object_id()), 'posts_per_page' => 4, 'orderby' => 'menu_order', 'order' => 'ASC'); $terms = hpv_product_terms(get_queried_object_id()); if ($terms) { $related_args['tax_query'] = array(array('taxonomy' => 'hpv_category', 'field' => 'term_id', 'terms' => wp_list_pluck($terms, 'term_id'))); } $related = new WP_Query($related_args); while ($related->have_posts()) { $related->the_post(); get_template_part('template-parts/product-card'); } wp_reset_postdata(); ?></div></div></section><?php endif; ?>
<?php get_template_part('template-parts/contact-section'); get_footer(); ?>
